exercises.starterCode:
// The var keyword is the original way to declare variables.
// Modern code uses let and const instead, but var still works.

// 1. A username (string)

// 2. Number of logins (number)

// 3. Whether the account is active (boolean)

exercises.solution:
var username = "admin";
var loginCount = 42;
var isActive = true;

exercises.testRunner:
(code) => {
  const r = new Function(code + '; return { username, loginCount, isActive };')();
  return [
    { pass: r.username === 'admin', description: 'username is "admin"', got: String(r.username) },
    { pass: r.loginCount === 42, description: 'loginCount is 42', got: String(r.loginCount) },
    { pass: r.isActive === true, description: 'isActive is true', got: String(r.isActive) },
    { pass: code.includes('var'), description: 'Uses var keyword', got: code.includes('var') ? 'Yes' : 'No' }
  ];
}

exercises.starterCode:
// The const keyword creates variables that cannot be reassigned.
// True constants use SCREAMING_SNAKE_CASE by convention.

// 1. The maximum possible score (number)

// 2. The name of the application (string)

// 3. Whether we are in production mode (boolean)

// 4. The value of pi (decimal number)

// 5. The speed of light in meters per second (number)

exercises.solution:
const MAX_SCORE = 100;
const APP_NAME = "CodeForge";
const IS_PRODUCTION = false;
const PI = 3.14159;
const SPEED_OF_LIGHT = 299792458;

exercises.testRunner:
(code) => {
  const r = new Function(code + '; return { MAX_SCORE, APP_NAME, IS_PRODUCTION, PI, SPEED_OF_LIGHT };')();
  return [
    { pass: r.MAX_SCORE === 100, description: 'MAX_SCORE is 100', got: String(r.MAX_SCORE) },
    { pass: r.APP_NAME === 'CodeForge', description: 'APP_NAME is "CodeForge"', got: String(r.APP_NAME) },
    { pass: r.IS_PRODUCTION === false, description: 'IS_PRODUCTION is false', got: String(r.IS_PRODUCTION) },
    { pass: Math.abs(r.PI - 3.14159) < 0.001, description: 'PI is 3.14159', got: String(r.PI) },
    { pass: r.SPEED_OF_LIGHT === 299792458, description: 'SPEED_OF_LIGHT is 299792458', got: String(r.SPEED_OF_LIGHT) },
    { pass: code.includes('const'), description: 'Uses const keyword', got: code.includes('const') ? 'Yes' : 'No' }
  ];
}

