exercises.starterCode:
/**
 * Demonstrates block scope. Declares a "message" variable with "outside",
 * declares another "message" inside an if block with "inside",
 * then returns the outer message.
 * Example: scopeTest() → "outside"
 */
function scopeTest() {

}

exercises.solution:
function scopeTest() {
  let message = "outside";
  if (true) {
    let message = "inside";
  }
  return message;
}

exercises.testRunner:
(code) => {
  const fn = new Function(code + '; return scopeTest;')();
  const result = fn();
  return [
    { pass: result === 'outside', description: 'scopeTest() returns "outside"', got: String(result) },
    { pass: code.includes('let message'), description: 'Uses let to declare message', got: code.includes('let message') ? 'Yes' : 'No' }
  ];
}

exercises.starterCode:
/**
 * Adds "!" to the end of each string in the array using .forEach().
 * Example: addExcitement(["hi", "bye"]) → ["hi!", "bye!"]
 * Example: addExcitement([]) → []
 */
function addExcitement(words) {

}

exercises.solution:
function addExcitement(words) {
  const result = [];
  words.forEach(function(word) {
    result.push(word + "!");
  });
  return result;
}

exercises.testRunner:
(code) => {
  const fn = new Function(code + '; return addExcitement;')();
  const r1 = fn(['hi', 'bye']);
  const r2 = fn(['hello']);
  const r3 = fn([]);
  return [
    { pass: JSON.stringify(r1) === JSON.stringify(['hi!', 'bye!']), description: 'addExcitement(["hi", "bye"]) returns ["hi!", "bye!"]', got: JSON.stringify(r1) },
    { pass: JSON.stringify(r2) === JSON.stringify(['hello!']), description: 'addExcitement(["hello"]) returns ["hello!"]', got: JSON.stringify(r2) },
    { pass: JSON.stringify(r3) === JSON.stringify([]), description: 'addExcitement([]) returns []', got: JSON.stringify(r3) },
    { pass: code.includes('.forEach'), description: 'Uses .forEach() method', got: code.includes('.forEach') ? 'Yes' : 'No' }
  ];
}

exercises.starterCode:
