  ];
}

exercises.starterCode:
/**
 * Returns only even numbers from an array using .filter().
 * Example: getEvens([1, 2, 3, 4, 5, 6]) → [2, 4, 6]
 * Example: getEvens([1, 3, 5]) → []
 */
function getEvens(nums) {

}

exercises.solution:
function getEvens(nums) {
  return nums.filter(function(num) {
    return num % 2 === 0;
  });
}

exercises.testRunner:
(code) => {
  const fn = new Function(code + '; return getEvens;')();
  const r1 = fn([1, 2, 3, 4, 5, 6]);
  const r2 = fn([1, 3, 5]);
  const r3 = fn([2, 4]);
  return [
    { pass: JSON.stringify(r1) === JSON.stringify([2, 4, 6]), description: 'getEvens([1, 2, 3, 4, 5, 6]) returns [2, 4, 6]', got: JSON.stringify(r1) },
    { pass: JSON.stringify(r2) === JSON.stringify([]), description: 'getEvens([1, 3, 5]) returns []', got: JSON.stringify(r2) },
    { pass: JSON.stringify(r3) === JSON.stringify([2, 4]), description: 'getEvens([2, 4]) returns [2, 4]', got: JSON.stringify(r3) },
    { pass: code.includes('.filter'), description: 'Uses .filter() method', got: code.includes('.filter') ? 'Yes' : 'No' }
  ];
}

