const temp = 45;

let grade;
if (score >= 90) { grade = "A"; } else if (score >= 80) { grade = "B"; } else if (score >= 70) { grade = "C"; } else if (score >= 60) { grade = "D"; } else { grade = "F"; }

let advice;
if (temp >= 85) { advice = "Stay hydrated"; } else if (temp >= 60) { advice = "Enjoy the weather"; } else if (temp >= 32) { advice = "Wear a jacket"; } else { advice = "Stay inside"; }

