// Functions can control loops using their parameters.
// Add three parameters: start, stop, and step

function buildRange() {
  // Add parameters: start, stop, and step
  // Create a variable called result and set it to ""
  // Write a for loop from start to stop (inclusive), incrementing by step
  // Inside the loop, add the current number and a space
