// A nested if places one conditional inside another.
// Useful for: validate first, then classify.
//
// Takes three side lengths: a, b, c
// Step 1: Check if the triangle is valid
//   - All sides must be positive
//   - Sum of any two sides must be greater than the third
// Step 2: If valid, classify as equilateral, isosceles, or scalene

function classifyTriangle(a, b, c) {
  // First check validity
  // Then classify the triangle type
}

exercises.solution:
function classifyTriangle(a, b, c) {
  if (a <= 0 || b <= 0 || c <= 0 || a + b <= c || a + c <= b || b + c <= a) {
    return "invalid";
  }
  if (a === b && b === c) {
    return "equilateral";
  } else if (a === b || a === c || b === c) {
    return "isosceles";
  } else {
    return "scalene";
  }
}

