exercises.starterCode:
// Returns a label and rating like "Delivery: Excellent"

function rateService(serviceType, score, isPremium) {
  // 1. Switch on serviceType for the label
  // 2. Ternary to adjust score for premium
  // 3. If/else to classify the adjusted score
}

exercises.solution:
function rateService(serviceType, score, isPremium) {
  let label;
  switch (serviceType) {
    case "delivery": label = "Delivery"; break;
    case "support": label = "Support"; break;
    case "quality": label = "Quality"; break;
    default: label = "General";
  }
  let adjusted = isPremium ? score + 2 : score;
  let rating;
  if (adjusted >= 8) {
    rating = "Excellent";
  } else if (adjusted >= 5) {
    rating = "Good";
  } else {
    rating = "Needs Improvement";
  }
  return label + ": " + rating;
}

exercises.testRunner:
