exercises.starterCode:
// .indexOf(target, fromIndex) can start searching from a specific index.
// Use this in a loop to find ALL positions of a value.
// Start searching from index 0, then from the position after each find.

// Return an array of all indices where the target appears
function findAllPositions(arr, target) {

}

exercises.solution:
function findAllPositions(arr, target) {
  const positions = [];
  let index = arr.indexOf(target);
  while (index !== -1) {
    positions.push(index);
    index = arr.indexOf(target, index + 1);
  }
  return positions;
}

