// .join(separator) combines array elements into a string.
// For a natural-language list, you need different logic
// depending on the number of items:
// 1 item: just return it
// 2 items: join with " and "
// 3+ items: join all but last with ", ", then add " and " + last item

// Return a formatted natural-language list string
function formatList(items) {

}

exercises.solution:
function formatList(items) {
  if (items.length === 1) {
    return items[0];
  }
  if (items.length === 2) {
    return items[0] + ' and ' + items[1];
  }
  return items.slice(0, -1).join(', ') + ' and ' + items[items.length - 1];
}

