// A nested loop is a loop inside another loop.
// The outer loop runs once for each row.
// For EACH outer iteration, the inner loop runs
// through ALL columns before the outer loop moves on.
//
// Syntax:
//   for (let i = 0; i < rows; i++) {
//     for (let j = 0; j < cols; j++) {
//       // this runs rows * cols times
//     }
//   }

// Return an array of "(row,col)" strings for every position
function gridCoordinates(rows, cols) {
  // Create an empty array to collect coordinates
  // Outer loop: iterate through each row
  //   Inner loop: iterate through each column
  //     Push the coordinate string "(i,j)" to the array
  // Return the array
}

exercises.solution:
function gridCoordinates(rows, cols) {
  const coords = [];
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      coords.push('(' + i + ',' + j + ')');
    }
  }
  return coords;
}

