exercises.starterCode:
// Build a right triangle of * characters as a multi-line string
// Separate rows with \n — do not add a trailing newline
function buildTriangle(n) {

}

exercises.solution:
function buildTriangle(n) {
  let result = '';
  for (let i = 1; i <= n; i++) {
    for (let j = 0; j < i; j++) {
      result += '*';
    }
    if (i < n) {
      result += '\n';
    }
  }
  return result;
}

exercises.starterCode:
// Build a right-aligned triangle with leading spaces
// Each row has (n - i - 1) spaces followed by (i + 1) stars
// Separate rows with \n — do not add a trailing newline
function buildReverseTriangle(n) {

}

exercises.solution:
function buildReverseTriangle(n) {
  let result = '';
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n - i - 1; j++) {
      result += ' ';
    }
    for (let j = 0; j < i + 1; j++) {
      result += '*';
    }
    if (i < n - 1) {
      result += '\n';
    }
  }
  return result;
}

