// Build a centered pyramid of * characters as a multi-line string
// Each row: (n - i - 1) spaces followed by (2 * i + 1) stars
// Separate rows with \n — do not add a trailing newline
function buildPyramid(n) {

}

exercises.solution:
function buildPyramid(n) {
  let result = '';
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n - i - 1; j++) {
      result += ' ';
    }
    for (let j = 0; j < 2 * i + 1; j++) {
      result += '*';
    }
    if (i < n - 1) {
      result += '\n';
    }
  }
  return result;
}

