exercises.solution:
function collectValidNames(entries) {
  const names = [];
  for (const entry of entries) {
    if (entry.trim() === 'STOP') {
      break;
    }
    if (entry.trim() === '') {
      continue;
    }
    names.push(entry.trim());
  }
  return names;
}

