exercises.solution:
function summarizeScores(students) {
  if (students.length === 0) {
    return { average: 0, highest: 0, passing: [] };
  }
  let sum = 0;
  let highest = students[0].score;
  const passing = [];
  for (let i = 0; i < students.length; i++) {
    sum += students[i].score;
    if (students[i].score > highest) {
      highest = students[i].score;
    }
    if (students[i].score >= 70) {
      passing.push(students[i].name);
    }
  }
  const average = Math.round((sum / students.length) * 10) / 10;
  return { average, highest, passing };
}

