exercises.solution:
function groupBy(objects, key) {
  const groups = {};
  for (let i = 0; i < objects.length; i++) {
    const groupKey = objects[i][key];
    if (groups[groupKey] === undefined) {
      groups[groupKey] = [];
    }
    groups[groupKey].push(objects[i]);
  }
  return groups;
}

