exercises.solution:
function applyDefaults(obj, defaults) {
  const result = {};
  for (const key in obj) {
    result[key] = obj[key];
  }
  for (const key in defaults) {
    if (result[key] === undefined) {
      result[key] = defaults[key];
    }
  }
  return result;
}

