exercises.solution:
function sumByKey(obj1, obj2) {
  const result = {};
  for (const key in obj1) {
    result[key] = obj1[key];
  }
  for (const key in obj2) {
    if (result[key] !== undefined) {
      result[key] += obj2[key];
    } else {
      result[key] = obj2[key];
    }
  }
  return result;
}

