exercises.solution:
function flattenObject(obj) {
  const result = {};
  for (const key in obj) {
    const value = obj[key];
    if (typeof value === "object" && value !== null && !Array.isArray(value)) {
      for (const innerKey in value) {
        result[key + "." + innerKey] = value[innerKey];
      }
    } else {
      result[key] = value;
    }
  }
  return result;
}

