exercises.solution:
function summarizeInventory(items) {
  const summary = {};
  for (let i = 0; i < items.length; i++) {
    const cat = items[i].category;
    if (summary[cat] === undefined) {
      summary[cat] = { count: 0, totalQty: 0, items: [] };
    }
    summary[cat].count++;
    summary[cat].totalQty += items[i].qty;
    summary[cat].items.push(items[i].name);
  }
  return summary;
}

